// Java 17 + Spring Boot 3.2 — jakarta.persistence (JPA), Hibernate runs it
import jakarta.persistence.*;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

@Entity
@Table(name = "customers")
public class Customer {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String name;

    @Column(unique = true)
    private String email;
    // JPA annotations above; Hibernate reads them and generates the SQL
}

@org.springframework.stereotype.Repository
public interface CustomerRepository extends JpaRepository<Customer, Long> {
    // JpaRepository is a JPA/Spring interface; Hibernate provides the runtime impl
    Optional<Customer> findByEmail(String email);
}
```
You write against the JPA contract; Hibernate turns it into real SQL.

