import jakarta.persistence.*;
import org.hibernate.Session;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional
public class OrderService {
    @PersistenceContext
    private EntityManager entityManager; // JPA standard interface

    public Order createOrder(Order order) {
        entityManager.persist(order); // JPA method
        return order;
    }

    public Order findById(Long id) {
        return entityManager.find(Order.class, id);
    }

    // Reach a Hibernate-only feature without leaving the JPA standard elsewhere
    public void enableBatching() {
        Session session = entityManager.unwrap(Session.class);
        session.setJdbcBatchSize(50); // Hibernate-specific tuning
    }
}
