import jakarta.persistence.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional
public class CustomerService {
    @PersistenceContext
    private EntityManager entityManager;

    public void demonstrateFirstLevelCache(Long customerId) {
        // First load: hits the database, stores in the first-level cache
        Customer customer1 = entityManager.find(Customer.class, customerId);

        // Second load: returns the cached instance, NO database hit
        Customer customer2 = entityManager.find(Customer.class, customerId);

        System.out.println(customer1 == customer2); // true — same object

        customer1.setName("Updated Name");
        System.out.println(customer2.getName());     // "Updated Name" — same object
    } // transaction ends -> first-level cache cleared
}
