@Transactional
public void printOrdersOptimized() {
    var orders = entityManager
        .createQuery("SELECT DISTINCT o FROM Order o JOIN FETCH o.items", Order.class)
        .getResultList();              // 1 query with a JOIN, all data loaded

    for (var order : orders) {
        System.out.println(order.getItems().size()); // no extra queries
    }
}

// Spring Data alternative: @EntityGraph on the repository method
interface OrderRepository extends JpaRepository<Order, Long> {
    @EntityGraph(attributePaths = "items")
    @Query("SELECT o FROM Order o")
    List<Order> findAllWithItems();
}
