import jakarta.persistence.*;
import java.util.*;

@Entity
@Table(name = "customers")
public class Customer {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "full_name", nullable = false)
    private String fullName;

    @Column(name = "email", unique = true)
    private String email;

    @OneToMany(mappedBy = "customer", cascade = CascadeType.ALL)
    private List<Order> orders = new ArrayList<>();
}
// Hibernate reads these annotations at startup and generates, for PostgreSQL:
//   CREATE TABLE customers (id BIGSERIAL PRIMARY KEY,
//     full_name VARCHAR(255) NOT NULL, email VARCHAR(255) UNIQUE);
//   persist(c)        -> INSERT INTO customers (full_name, email) VALUES (?, ?);
//   findById(1L)      -> SELECT id, full_name, email FROM customers WHERE id = ?;
