import jakarta.persistence.*;

// JPA standard: persist() inserts a transient entity, returns void
@PersistenceContext EntityManager em;
void createWithJpa(Order order) {
    em.persist(order);            // order must have NO id yet
}

// Hibernate native: save() returns the generated id immediately
// Long id = (Long) session.save(order);

// Modern Spring Data JPA: one method handles insert AND update
interface OrderRepository extends JpaRepository<Order, Long> {}

class OrderService {
    private final OrderRepository repo;
    OrderService(OrderRepository repo) { this.repo = repo; }

    Order saveOrder(Order order) {
        // null id  -> SimpleJpaRepository calls persist() (INSERT)
        // set id   -> it calls merge()  (SELECT then INSERT/UPDATE)
        return repo.save(order);
    }
}
